import Image from "next/image";
import { cn } from "@/lib/utils";

/**
 * The areniX logo supplied by the owner. `tone="light"` is the off white version for navy
 * surfaces (header, footer, dashboard). `tone="dark"` is the navy version for light surfaces.
 * Assets are generated by `node scripts/build-brand-assets.mjs <logo.png>`.
 */
export function Wordmark({
  className,
  tone = "light",
  priority = false,
}: {
  className?: string;
  tone?: "light" | "dark";
  priority?: boolean;
}) {
  const src = tone === "dark" ? "/brand/logo.png" : "/brand/logo-on-dark.png";
  return (
    <Image
      src={src}
      alt="areniX"
      width={1600}
      height={654}
      priority={priority}
      className={cn("h-7 w-auto", className)}
    />
  );
}

/** Large decorative logo for the footer. */
export function WordmarkGiant({
  className,
  tone = "light",
}: {
  className?: string;
  tone?: "light" | "dark";
}) {
  const src = tone === "dark" ? "/brand/logo.png" : "/brand/logo-on-dark.png";
  return (
    <div aria-hidden="true" className={cn("select-none", className)}>
      <Image
        src={src}
        alt=""
        width={1600}
        height={654}
        className="h-auto w-full max-w-[720px]"
      />
    </div>
  );
}

/** The orange X alone. */
export function Mark({
  className,
  tone = "light",
}: {
  className?: string;
  tone?: "light" | "dark";
}) {
  const src = tone === "dark" ? "/brand/mark.png" : "/brand/mark-on-dark.png";
  return (
    <Image
      src={src}
      alt="areniX"
      width={1024}
      height={1024}
      className={cn("size-8", className)}
    />
  );
}
